/**
 * @file
 * Styles for the OpenFed RSS feed block.
 */

/* Block wrapper */
.openfed-rss-feed {
  margin: 0;
  padding: 0;
}

/* Items list */
.openfed-rss-feed__items {
  list-style: none;
  margin: 0;
  padding: 0 0 0.5rem 0;
}

/* Single item */
.openfed-rss-feed__item {
  border-bottom: 1px solid #e0e0e0;
  padding: 0.5rem 0;
}

/* Item title */
.openfed-rss-feed__item-title {
  margin-bottom: 0.25rem;
}

/* Item meta (date + link) */
.openfed-rss-feed__item-meta {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
}

/* Item date */
.openfed-rss-feed__item-date {
  color: #666;
  font-size: 0.875rem;
}

/* Item read more link */
.openfed-rss-feed__item-link {
  color: #005ea8;
  font-weight: 500;
  text-decoration: none;
}

